// Asteroid Escape game
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 400;
  const H = canvas.height = canvas.clientHeight || 600;

  // Ship
  const ship = { x: W / 2, y: H - 40, w: 30, h: 30, speed: 4 };
  let fuel = 100; // percent
  let score = 0;
  const keys = {};
  document.addEventListener('keydown', e => keys[e.key] = true);
  document.addEventListener('keyup', e => keys[e.key] = false);

  // Entities
  const asteroids = [];
  const fuels = [];
  let lastAsteroid = 0, lastFuel = 0;
  let gameOver = false;

  function spawnAsteroid() {
    const size = 20 + Math.random() * 30;
    asteroids.push({
      x: Math.random() * (W - size),
      y: -size,
      w: size,
      h: size,
      speed: 1 + Math.random() * 2 + score / 5000
    });
  }

  function spawnFuel() {
    const size = 15;
    fuels.push({
      x: Math.random() * (W - size),
      y: -size,
      w: size,
      h: size,
      speed: 1.5
    });
  }

  function update(dt) {
    if (gameOver) return;
    // Ship movement
    if (keys.ArrowLeft) ship.x -= ship.speed;
    if (keys.ArrowRight) ship.x += ship.speed;
    if (keys.ArrowUp) ship.y -= ship.speed;
    if (keys.ArrowDown) ship.y += ship.speed;
    // Keep within bounds
    ship.x = Math.max(0, Math.min(W - ship.w, ship.x));
    ship.y = Math.max(0, Math.min(H - ship.h, ship.y));

    // Spawn asteroids every 1‑1.5s
    if (Date.now() - lastAsteroid > 1000 + Math.random() * 500) {
      spawnAsteroid();
      lastAsteroid = Date.now();
    }
    // Spawn fuel occasionally
    if (Date.now() - lastFuel > 5000 + Math.random() * 5000) {
      spawnFuel();
      lastFuel = Date.now();
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      if (a.y > H) asteroids.splice(i, 1);
    }
    // Update fuels
    for (let i = fuels.length - 1; i >= 0; i--) {
      const f = fuels[i];
      f.y += f.speed;
      if (f.y > H) fuels.splice(i, 1);
    }

    // Collisions
    function rectCollision(r1, r2) {
      return !(r2.x > r1.x + r1.w ||
               r2.x + r2.w < r1.x ||
               r2.y > r1.y + r1.h ||
               r2.y + r2.h < r1.y);
    }
    for (let i = asteroids.length - 1; i >= 0; i--) {
      if (rectCollision(ship, asteroids[i])) { gameOver = true; break; }
    }
    for (let i = fuels.length - 1; i >= 0; i--) {
      if (rectCollision(ship, fuels[i])) {
        fuel = Math.min(100, fuel + 20);
        fuels.splice(i, 1);
      }
    }

    // Fuel consumption & score
    fuel -= dt * 0.01; // drains over time
    if (fuel <= 0) gameOver = true;
    score += dt;
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // Ship
    ctx.fillStyle = '#0f0';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Asteroids
    ctx.fillStyle = '#777';
    asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.w, a.h));
    // Fuel cells
    ctx.fillStyle = '#ff0';
    fuels.forEach(f => ctx.fillRect(f.x, f.y, f.w, f.h));
    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '14px sans-serif';
    ctx.fillText(`Score: ${Math.floor(score / 1000)}`, 10, 20);
    ctx.fillText(`Fuel: ${Math.max(0, Math.floor(fuel))}%`, 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#f00';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', W / 2 - 80, H / 2);
    }
  }

  let last = performance.now();
  function loop(now) {
    const dt = now - last;
    last = now;
    if (!gameOver) update(dt);
    draw();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
